export const EmailAttachmentSchema = {
  type: "object",
  additionalProperties: false,
  required: ["filename", "content"],
  description:
    'A file attached to an email. Put the base64-encoded bytes in `content` and the\nrecipient-facing name in `filename`. To show an image inline, set `content_id`\nand reference it from the HTML body with `<img src="cid:..."/>`.\n\nThe generated message is limited to 20 MB across the HTML body, text body,\nattachments, and inline images after base64 and MIME encoding. Keep raw\nattachment content at or below 15 MB to leave room for encoding and the body.\n\nBatch sends apply the same 20 MB limit to each message and to the full request\nbody. Executable and script content types are rejected.\n',
  properties: {
    filename: {
      type: "string",
      minLength: 1,
      maxLength: 255,
      description: "The name the recipient sees on the attachment.",
      example: "invoice.pdf",
    },
    content: {
      type: "string",
      format: "byte",
      minLength: 1,
      description:
        "Base64-encoded file bytes. The encoded value and MIME wrapping count toward the 20 MB message limit.",
    },
    content_type: {
      type: "string",
      description:
        "The file's MIME type. If omitted, the API infers it from the extension in `filename`. The API rejects executable and script types based on this value.",
      example: "application/pdf",
    },
    content_id: {
      type: "string",
      minLength: 1,
      maxLength: 128,
      pattern: "^[A-Za-z0-9._-]+$",
      description:
        'An RFC 2392 Content-ID for an inline file. Reference it from the HTML body with `<img src="cid:{content_id}"/>`. Omit it to send a downloadable attachment.',
      example: "invoice-logo",
    },
  },
} as const;

