export const SMSKeywordRuleCreateSchema = {
  type: "object",
  additionalProperties: false,
  required: ["operation"],
  properties: {
    operation: {
      $ref: "#/components/schemas/SMSKeywordOperation",
    },
    country: {
      type: ["string", "null"],
      minLength: 2,
      maxLength: 2,
      description:
        "The country this rule applies in, as an ISO 3166-1 alpha-2 code. It matches a message two ways: one received on any of your numbers in this country, and one sent by a subscriber whose own number is in it, wherever they text you. Rules for the country a message arrives in always outrank rules for the country its sender is in; within each, your rule wins over Bird's keywords for that country. To confine a rule to one of your numbers, set `number` instead. Required for `stop`, `start` and `help`, because those replace what Bird ships for one country and a worldwide rule would replace every country's. Omit it only for `custom`, which then applies everywhere you send. Derived from `number` when you supply an E.164 number and leave this out; a short code carries no country, so a rule for one must name it.\n",
      example: "NL",
    },
    language: {
      type: ["string", "null"],
      minLength: 2,
      description:
        "Which language this rule replaces, in countries where Bird ships keywords in more than one. Required there and rejected elsewhere. Listing the country's rules shows whether it applies and which languages are available.\n",
      example: "fr",
    },
    number: {
      type: ["string", "null"],
      minLength: 1,
      description:
        "Narrows the rule to one number you hold, in E.164 format or as a short code. Omit to cover every number you hold in the country. The number must be one of yours and able to receive messages.\n",
      example: "+18005551234",
    },
    keywords: {
      type: "array",
      description:
        "Extra keywords to match, on top of the ones Bird already ships for this operation and country. Omit to keep Bird's keywords and change only the reply, including keywords Bird adds later. You cannot remove one of Bird's keywords, and a keyword Bird has bound to another operation cannot be reused here. Required for `custom`, which inherits none.\n",
      items: {
        type: "string",
        minLength: 1,
      },
      example: ["pizza", "menu"],
    },
    reply: {
      type: ["string", "null"],
      minLength: 1,
      description:
        "The message to send back when a keyword matches, except on a `confirm` rule, which never sends one whatever this is set to. Set it to null together with `confirmed_self_managed` to send nothing at all.\n",
      example:
        "You have been unsubscribed and will receive no further messages.",
    },
    confirmed_self_managed: {
      type: "boolean",
      description:
        "Set this with `reply: null` to confirm you send this reply from your own system, which switches Bird's auto-reply off for the rule. Required to send no reply, and rejected when a reply is given, so the two can never disagree.\n",
      example: true,
    },
  },
} as const;

