export const DomainCapabilitySchema = {
  type: "object",
  additionalProperties: false,
  required: ["status"],
  properties: {
    status: {
      type: "string",
      minLength: 1,
      readOnly: true,
      description:
        "Capability verification status.\n\n- `pending`: verification has not run, or is currently running.\n- `verified`: all DNS records for this capability resolved with the\n  expected values.\n- `warning`: a record for this capability verified before and a recent\n  check no longer matches, but it is still within the grace period.\n  Sending is not yet affected; fix it before the grace period ends.\n- `failed`: DNS records resolved but at least one value is wrong.\n  Update your DNS to recover.\n- `temporary_failure`: DNS lookup failed transiently. Verification retries\n  automatically; do not change DNS records unless they are incorrect.\n- `not_configured`: the capability is not set up on this domain\n  (for example, no tracking domain configured).\n",
      enum: [
        "pending",
        "verified",
        "warning",
        "failed",
        "temporary_failure",
        "not_configured",
      ],
      example: "verified",
    },
    domain: {
      type: ["string", "null"],
      readOnly: true,
      description:
        "Hostname this capability is configured with: the return-path domain, the tracking domain, or the domain where the DMARC policy was found. `null` when not applicable or not configured.\n",
    },
    pending: {
      $ref: "#/components/schemas/DomainCapabilityPending",
    },
    reason: {
      type: ["string", "null"],
      readOnly: true,
      description:
        "Machine-readable reason code for a failed capability status. Only set when\n`status` is `failed`. Use this to display a specific message to users rather\nthan a generic failure message.\n\n- `tracking_domain_in_use`: the link tracking subdomain is already claimed\n  by another organization.\n",
    },
  },
} as const;

